import{c as e,Q as r,j as n,m as a}from"./chunks/framework.BqPkuuVc.js";const u=JSON.parse('{"title":"Tracking","description":"","frontmatter":{},"headers":[],"relativePath":"user/running-the-event/tracking.md","filePath":"user/running-the-event/tracking.md"}'),o={name:"user/running-the-event/tracking.md"};function s(i,t,h,l,d,g){return r(),n("div",null,[...t[0]||(t[0]=[a('<h1 id="tracking" tabindex="-1">Tracking <a class="header-anchor" href="#tracking" aria-label="Permalink to &quot;Tracking&quot;">​</a></h1><p><strong>Audience:</strong> Timing operators looking after the meshO Athlete units (GPS trackers) competitors carry.</p><p>How to use the <strong>Tracking</strong> screen to keep an eye on the trackers: which are reporting, which have gone quiet, which are running low, and which are sending to Livelox.</p><h2 id="what-it-s-for" tabindex="-1">What it&#39;s for <a class="header-anchor" href="#what-it-s-for" aria-label="Permalink to &quot;What it&#39;s for&quot;">​</a></h2><p><strong>Tracking</strong> is a table of the <strong>meshO Athlete units</strong> heard by meshO Prime: one row per unit. It&#39;s about the trackers themselves, not results. To see where they are on a map, use <a href="./live-view">Live view</a>. For split times and positions, use the <a href="./../screens/tv-screens">leaderboard screens</a> and <a href="./../screens/commentary">Commentary</a>.</p><p>Open the event and choose <strong>Tracking</strong> under <strong>Event live</strong>. It&#39;s there while the event is running, and only for an event that uses meshO Prime (<strong>Event details → Radio Controls → meshO Prime</strong>). A unit appears once Prime has heard from it.</p><h2 id="the-table" tabindex="-1">The table <a class="header-anchor" href="#the-table" aria-label="Permalink to &quot;The table&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Column</th><th>What it shows</th></tr></thead><tbody><tr><td><strong>ID</strong></td><td>The unit&#39;s serial number.</td></tr><tr><td><strong>Status</strong></td><td>How recently the unit reported, and whether it has a position (below).</td></tr><tr><td><strong>Battery</strong></td><td>The battery level. Click it for the unit&#39;s battery history.</td></tr><tr><td><strong>Last location</strong></td><td>Where it last reported being. Click it to see the unit&#39;s track on a map.</td></tr><tr><td><strong>Last seen</strong></td><td>When Prime last heard from it, and how long ago.</td></tr><tr><td><strong>Livelox</strong></td><td>Whether the unit&#39;s track is sent to Livelox, and how many positions have been sent and are still waiting.</td></tr><tr><td><strong>Actions</strong></td><td><strong>Download GPX track</strong>, <strong>Clear all locations</strong> and <strong>Delete athlete and all data</strong>.</td></tr></tbody></table><h3 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Good</strong></td><td>Heard in the last 30 seconds, with a position from the last 2 minutes.</td></tr><tr><td><strong>Acquiring</strong></td><td>Heard recently, but without a recent position: usually a unit still finding its GPS fix, just switched on or under cover.</td></tr><tr><td><strong>OK</strong></td><td>Heard in the last 2 minutes, with a recent position.</td></tr><tr><td><strong>Warning</strong></td><td>Not heard for 2 to 5 minutes.</td></tr><tr><td><strong>Stale</strong></td><td>Not heard for more than 5 minutes.</td></tr></tbody></table><p>A <strong>Warning</strong> or <strong>Stale</strong> unit is out of radio range, switched off, flat, or carried somewhere the network doesn&#39;t reach. Its last location is where to start looking.</p><h2 id="before-the-start" tabindex="-1">Before the start <a class="header-anchor" href="#before-the-start" aria-label="Permalink to &quot;Before the start&quot;">​</a></h2><ol><li>Switch on every unit you&#39;re handing out, with Prime connected and the event running.</li><li>Check each one appears in the table and reaches <strong>Good</strong>. <strong>Acquiring</strong> for more than a few minutes usually means the unit can&#39;t see the sky.</li><li>Check the batteries: replace or charge any that are low now, rather than have them go flat on course.</li></ol><h2 id="during-the-event" tabindex="-1">During the event <a class="header-anchor" href="#during-the-event" aria-label="Permalink to &quot;During the event&quot;">​</a></h2><ul><li><strong>Units going quiet</strong>: watch for <strong>Warning</strong> and <strong>Stale</strong>. Click <strong>Last location</strong> to see the unit&#39;s track up to the moment it went quiet.</li><li><strong>Low batteries</strong>: the battery history shows how fast each one is falling.</li></ul><h2 id="livelox" tabindex="-1">Livelox <a class="header-anchor" href="#livelox" aria-label="Permalink to &quot;Livelox&quot;">​</a></h2><p>Switch <strong>Livelox</strong> on for a unit to send its positions to Livelox, about every five seconds while it has new ones. Manager identifies the unit to Livelox by its serial number (the <strong>ID</strong> column), so whoever is carrying it has to be set up against that number on the Livelox side. With Livelox on, the column shows how many positions have been <strong>sent</strong> and how many are still <strong>pending</strong>. Pending ones go when the connection allows.</p><h2 id="tidying-up" tabindex="-1">Tidying up <a class="header-anchor" href="#tidying-up" aria-label="Permalink to &quot;Tidying up&quot;">​</a></h2><ul><li><strong>Download GPX track</strong> saves the unit&#39;s route as a GPX file for mapping or route-analysis software.</li><li><strong>Clear all locations</strong> removes the positions recorded for the unit, for example after a test run before the event. It asks first.</li><li><strong>Delete athlete and all data</strong> removes the unit and everything recorded for it. It can&#39;t be undone.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./live-view">Live view</a></li><li><a href="./connecting-prime-and-radios">Connecting meshO Prime and radios</a></li><li><a href="./../after-the-event/exports#gps-tracks">Exporting data</a></li><li><a href="./../screens/commentary">Commentary</a></li></ul>',21)])])}const m=e(o,[["render",s]]);export{u as __pageData,m as default};
